import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents banker\'s rounding half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros formats cents as euros', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(0), '€0.00');
});

test('formatEuros handles negative amounts', () => {
  assert.equal(formatEuros(-123456), '-€1,234.56');
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros parses euro amounts', () => {
  const r1 = parseEuros('12');
  assert.equal(r1.ok, true);
  assert.equal(r1.value, 1200);

  const r2 = parseEuros('12.5');
  assert.equal(r2.ok, true);
  assert.equal(r2.value, 1250);

  const r3 = parseEuros('1,234.56');
  assert.equal(r3.ok, true);
  assert.equal(r3.value, 123456);
});

test('RATES constant has EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR cents to USD', () => {
  const r = convert(50000, 'USD');
  assert.equal(r.ok, true);
  // 50000 * 1.085 = 54250
  assert.equal(r.value, 54250);
});

test('convert EUR cents to GBP', () => {
  const r = convert(50000, 'GBP');
  assert.equal(r.ok, true);
  // 50000 * 0.8425 = 42125
  assert.equal(r.value, 42125);
});

test('convert EUR cents to EUR', () => {
  const r = convert(50000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 50000);
});

test('convert returns UNKNOWN_CURRENCY for invalid currency', () => {
  const r = convert(50000, 'JPY');
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert rounds correctly', () => {
  // 100 EUR * 1.085 = 108.5 cents, should round
  const r = convert(100, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 109); // 108.5 rounds to 109 (banker's rounding)
});

test('convert handles zero', () => {
  const r = convert(0, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('convert handles negative amounts', () => {
  const r = convert(-50000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, -54250);
});

test('formatMoney formats EUR with symbol', () => {
  const r = formatMoney(50000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€500.00');
});

test('formatMoney formats USD with dollar sign', () => {
  const r = formatMoney(50000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, '$542.50');
});

test('formatMoney formats GBP with pound sign', () => {
  const r = formatMoney(50000, 'GBP');
  assert.equal(r.ok, true);
  assert.equal(r.value, '£421.25');
});

test('formatMoney returns UNKNOWN_CURRENCY for invalid currency', () => {
  const r = formatMoney(50000, 'JPY');
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('formatMoney formats with 2 decimals', () => {
  const r1 = formatMoney(5, 'EUR');
  assert.equal(r1.ok, true);
  assert.equal(r1.value, '€0.05');

  const r2 = formatMoney(50000, 'USD');
  assert.equal(r2.ok, true);
  assert(r2.value.match(/\.\d{2}$/));
});

test('formatMoney handles zero', () => {
  const r = formatMoney(0, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€0.00');
});

test('formatMoney handles negative amounts', () => {
  const r1 = formatMoney(-50000, 'EUR');
  assert.equal(r1.ok, true);
  assert.equal(r1.value, '-€500.00');

  const r2 = formatMoney(-50000, 'USD');
  assert.equal(r2.ok, true);
  assert.equal(r2.value, '-$542.50');
});

test('formatMoney with small amounts', () => {
  const r = formatMoney(1, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€0.01');
});

test('formatMoney with large amounts', () => {
  const r = formatMoney(123456789, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€1,234,567.89');
});

test('convert and formatMoney consistency', () => {
  const cents = 100000;
  const convertResult = convert(cents, 'USD');
  const formatResult = formatMoney(cents, 'USD');

  assert.equal(convertResult.ok, true);
  assert.equal(formatResult.ok, true);

  // formatMoney should use the converted amount
  const convertedCents = convertResult.value;
  const expectedFormatted = `$${(convertedCents / 100).toFixed(2)}`;
  assert.equal(formatResult.value, expectedFormatted);
});

test('convert multiple currencies same amount', () => {
  const cents = 100000;
  const eur = convert(cents, 'EUR');
  const usd = convert(cents, 'USD');
  const gbp = convert(cents, 'GBP');

  assert.equal(eur.ok, true);
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);

  // USD should be highest (largest multiplier)
  assert(usd.value > eur.value);
  assert(eur.value > gbp.value);
});

test('formatMoney all currencies', () => {
  const cents = 25000;
  const eur = formatMoney(cents, 'EUR');
  const usd = formatMoney(cents, 'USD');
  const gbp = formatMoney(cents, 'GBP');

  assert.equal(eur.ok, true);
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);

  assert(eur.value.includes('€'));
  assert(usd.value.includes('$'));
  assert(gbp.value.includes('£'));
});

test('RATES is accessible', () => {
  assert(typeof RATES === 'object');
  assert(RATES.EUR !== undefined);
  assert(RATES.USD !== undefined);
  assert(RATES.GBP !== undefined);
});

