test('convert and formatMoney consistency', () => {
  const cents = 100000;
  const convertResult = convert(cents, 'USD');
  const formatResult = formatMoney(cents, 'USD');

  assert.equal(convertResult.ok, true);
  assert.equal(formatResult.ok, true);

  // formatMoney should use the converted amount
  const convertedCents = convertResult.value;
  const expectedFormatted = `$${(convertedCents / 100).toFixed(2)}`;
  assert.equal(formatResult.value, expectedFormatted);
});

test('convert multiple currencies same amount', () => {
  const cents = 100000;
  const eur = convert(cents, 'EUR');
  const usd = convert(cents, 'USD');
  const gbp = convert(cents, 'GBP');

  assert.equal(eur.ok, true);
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);

  // USD should be highest (largest multiplier)
  assert(usd.value > eur.value);
  assert(eur.value > gbp.value);
});

test('formatMoney all currencies', () => {
  const cents = 25000;
  const eur = formatMoney(cents, 'EUR');
